  const ow = await generateOverworldChunks(0xC0FFEE);
  const sandCrabs = allSpawns(ow).filter((spawn) =>
    spawn.kind === "monster" && spawn.params?.identity === "sand_crab"
  );
  assert(sandCrabs.length > 0, "expected sand crab overworld spawns");
